"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/credit-usage/variants/01-trend";
import View1 from "./components/credit-usage/variants/02-breakdown";
const variants={"trend":View0,"breakdown":View1};
export interface ArtemisCreditUsageProps { className?: string; variant?: "trend" | "breakdown"; }
export function ArtemisCreditUsage({className,variant="trend"}:ArtemisCreditUsageProps) {const View=variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { useId as useArtemisInstanceId } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { type KeyboardEvent, type ReactNode, useRef, useState } from "react";
import { ArtemisSegmentedTabs } from "../../../foundations/segmented-tabs";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PRESS, ARTEMIS_SPRING_SWAP } from "../../../lib/ease";
import { NumberTicker } from "./01-trend/number-ticker";
const SERIES = [
    { key: "drafting", label: "Drafting", color: "art:bg-blue-500", stroke: "art:stroke-blue-500" },
    { key: "analysis", label: "Analysis", color: "art:bg-orange-500", stroke: "art:stroke-orange-500" },
    { key: "translation", label: "Translation", color: "art:bg-teal-500", stroke: "art:stroke-teal-500" },
    { key: "sync", label: "Data sync", color: "art:bg-lime-500", stroke: "art:stroke-lime-500" },
] as const;
type SeriesKey = (typeof SERIES)[number]["key"];
const DAYS: readonly (readonly [
    number,
    number,
    number,
    number
])[] = [
    [3753, 4750, 2674, 2381],
    [3761, 4050, 2454, 1684],
    [4020, 4974, 2443, 1761],
    [1611, 2100, 1301, 957],
    [1896, 2546, 1322, 919],
    [4130, 4597, 2808, 2280],
    [3352, 4278, 2124, 2073],
    [3975, 4410, 2392, 1807],
    [3653, 4493, 2363, 2199],
    [4583, 5740, 2726, 2049],
    [2313, 2376, 1196, 1170],
    [2417, 3180, 1735, 1317],
    [4447, 6033, 3381, 2701],
    [4205, 5804, 2855, 2741],
    [5032, 5148, 2912, 2397],
    [4401, 5253, 3225, 2514],
    [5285, 5138, 3144, 2628],
    [2155, 2507, 1638, 1065],
    [1833, 2624, 1485, 957],
    [5053, 6681, 3521, 2855],
    [5602, 6136, 3126, 2783],
    [5178, 6899, 3697, 2589],
    [7227, 7462, 4531, 3216],
];
const CYCLE_DAYS = 30;
const TODAY = DAYS.length - 1;
const DOMAIN = Math.max(...DAYS.map((d) => d[0] + d[1] + d[2] + d[3])) * 1.08;
const BUDGET = Math.round(500000 / CYCLE_DAYS);
type Range = "14d" | "cycle";
const RANGES = [
    { value: "14d", label: <>{"14"}{" days"}</> },
    { value: "cycle", label: "Full cycle" },
] as const;
const WORKFLOWS = [
    { name: "Ticket triage", series: 1, points: "0.0,21.5 4.9,22.3 9.8,20.3 14.8,17.2 19.7,20.7 24.6,17.6 29.5,14.5 34.5,8.7 39.4,9.1 44.3,14.5 49.2,4.8 54.2,5.6 59.1,7.9 64.0,1.8", value: "46.3k", up: true, pct: "18" },
    { name: "Market scan", series: 1, points: "0.0,9.4 4.9,22.3 9.8,3.5 14.8,6.0 19.7,13.7 24.6,1.8 29.5,12.0 34.5,6.9 39.4,12.9 44.3,1.8 49.2,6.0 54.2,2.6 59.1,6.9 64.0,12.0", value: "38.1k", up: true, pct: "6" },
    { name: "Help localizer", series: 2, points: "0.0,8.8 4.9,1.8 9.8,6.0 14.8,5.3 19.7,10.9 24.6,16.6 29.5,14.5 34.5,12.4 39.4,22.3 44.3,20.1 49.2,16.6 54.2,7.4 59.1,13.1 64.0,22.3", value: "33.6k", up: false, pct: "9" },
    { name: "CRM enrichment", series: 3, points: "0.0,22.3 4.9,18.9 9.8,14.3 14.8,4.4 19.7,8.4 24.6,15.6 29.5,13.0 34.5,16.3 39.4,9.0 44.3,1.8 49.2,2.4 54.2,9.7 59.1,4.4 64.0,7.0", value: "29.5k", up: true, pct: "3" },
    { name: "Proposal drafts", series: 0, points: "0.0,22.3 4.9,15.7 9.8,14.3 14.8,18.1 19.7,12.9 24.6,12.9 29.5,7.3 34.5,11.5 39.4,12.5 44.3,5.0 49.2,1.8 54.2,6.4 59.1,1.8 64.0,4.5", value: "27.9k", up: true, pct: "24" },
] as const;
const k = (v: number) => (v < 1000 ? `${v}` : `${(v / 1000).toFixed(1)}k`);
const pct = (v: number) => `${v}%`;
const num = (v: number) => v.toLocaleString("en-US");
const BAR = "art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:relative art:flex art:h-full art:min-w-0 art:flex-1 art:items-end art:disabled:opacity-100 art:rounded-full";
const LEGEND = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:h-8 art:gap-1.5 art:px-3 art:text-xs art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:transition-opacity";
const DIM = { duration: 0.18, ease: "easeOut" } as const;
const TIP_EXIT = { duration: 0.14, ease: [0.4, 0, 1, 1] } as const;
const REVEAL_HIDDEN = { opacity: 0, filter: "blur(6px)", y: 14 };
const REVEAL_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
const reveal = (delay: number) => ({ duration: 0.55, ease: ARTEMIS_EASE_OUT, delay });
export default function CreditUsageTrend() {
const artemisInstanceId = useArtemisInstanceId();

    const reduce = useReducedMotion();
    const [range, setRange] = useState<Range>("cycle");
    const [hidden, setHidden] = useState<ReadonlySet<SeriesKey>>(new Set());
    const [active, setActive] = useState<number | null>(null);
    const [highlight, setHighlight] = useState<number | null>(null);
    const bars = useRef<(HTMLButtonElement | null)[]>([]);
    const visible = SERIES.map((s) => !hidden.has(s.key));
    const totalOf = (day: readonly number[]) => day.reduce((sum, v, i) => sum + (visible[i] ? v : 0), 0);
    const used = DAYS.reduce((sum, d) => sum + totalOf(d), 0);
    const average = Math.round(used / DAYS.length);
    const projected = average * CYCLE_DAYS;
    const first = range === "cycle" ? 0 : DAYS.length - 14;
    const shown = DAYS.slice(first);
    const projectedCount = range === "cycle" ? CYCLE_DAYS - DAYS.length : 0;
    const count = shown.length + projectedCount;
    const last = shown.length - 1;
    const grow = (i: number) => (reduce ? { duration: 0 } : { ...ARTEMIS_SPRING_LAYOUT, delay: 0.3 + i * 0.018 });
    const instant = (t: object) => (reduce ? { duration: 0 } : t);
    const toggle = (key: SeriesKey) => setHidden((prev) => {
        const next = new Set(prev);
        if (next.has(key))
            next.delete(key);
        else if (SERIES.length - prev.size > 1)
            next.add(key);
        return next;
    });
    const onBarKey = (e: KeyboardEvent<HTMLButtonElement>, i: number) => {
        const to = e.key === "ArrowRight" ? Math.min(last, i + 1) : e.key === "ArrowLeft" ? Math.max(0, i - 1) : e.key === "Home" ? 0 : e.key === "End" ? last : null;
        if (to === null)
            return;
        e.preventDefault();
        bars.current[to]?.focus();
    };
    const tip = active === null || active > last
        ? null
        : (() => {
            const day = shown[active];
            const total = totalOf(day);
            const left = ((active + 0.5) / count) * 100;
            return { day, total, left, top: Math.min(48, (1 - total / DOMAIN) * 100 - 4), flip: left > 54.9, date: first + active + 1 };
        })();
    const roving = active ?? last;
    return (<>
      <section aria-labelledby={`${artemisInstanceId}-credit-trend-title`} className="art:w-full art:font-sans art:text-foreground">
        <div className="art:mx-auto art:w-full art:max-w-6xl">
          <motion.div className="art:flex art:flex-col art:gap-5 art:@min-[640px]/artemis:flex-row art:@min-[640px]/artemis:items-end art:@min-[640px]/artemis:justify-between" initial={REVEAL_HIDDEN} animate={REVEAL_SHOWN} transition={instant(reveal(0))}>
            <div>
              <h2 id={`${artemisInstanceId}-credit-trend-title`} className="art:font-medium art:text-4xl art:tracking-tight">
                {"Daily credit spend"}
              </h2>
              <p className="art:mt-2 art:text-muted-foreground">{"Track the pace of this cycle and spot the days that ran hot."}</p>
            </div>
            <div>
              <ArtemisSegmentedTabs items={RANGES} value={range} onValueChange={(v) => {
            setActive(null);
            setRange(v as Range);
        }} ariaLabel="Chart range" layout="position"/>
            </div>
          </motion.div>
          <motion.dl className="art:mt-8 art:grid art:gap-4 art:@min-[640px]/artemis:grid-cols-3" initial={REVEAL_HIDDEN} animate={REVEAL_SHOWN} transition={instant(reveal(0.08))}>
            <Stat label="Used so far" value={num(used)}/>
            <Stat label="Daily average" value={num(average)}/>
            <Stat label="Projected by Nov 1" value={num(projected)} badge={<span className="art:rounded-full art:border art:px-2 art:py-0.5 art:font-medium art:text-xs art:border-emerald-500/25 art:bg-emerald-500/10 art:text-emerald-700 art:dark:text-emerald-300" style={{ opacity: 1, transform: "none" }}>
                  {"On pace"}
                </span>}/>
          </motion.dl>
          <div className="art:mt-4 art:grid art:gap-4 art:@min-[1024px]/artemis:grid-cols-[minmax(0,1fr)_20rem]">
            <motion.div className="art:min-w-0 art:rounded-3xl art:border art:border-border art:p-5 art:@min-[640px]/artemis:p-6" initial={REVEAL_HIDDEN} animate={REVEAL_SHOWN} transition={instant(reveal(0.16))}>
              <div className="art:flex art:items-baseline art:justify-between art:gap-3">
                <h3 className="art:font-medium art:text-xl">{"Spend per day"}</h3>
                <p className="art:hidden art:text-muted-foreground art:text-xs art:@min-[640px]/artemis:block">{"Hover or use arrow keys to inspect a day"}</p>
              </div>
              <figure aria-label="Spend per day" className="art:m-0 art:w-full art:mt-8">
                <div className="art:relative art:h-64">
                  <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-x-0 art:z-10 art:border-foreground/30 art:border-t art:border-dashed" style={{ bottom: `${(BUDGET / DOMAIN) * 100}%` }}>
                    <span className="art:absolute art:-top-6 art:right-0 art:rounded-full art:border art:border-border art:bg-background art:px-2 art:py-0.5 art:text-muted-foreground art:text-xs">{`Daily budget ${k(BUDGET)}`}</span>
                  </div>
                  <AnimatePresence>
                    {tip && (<motion.div key="tip" aria-hidden="true" className="art:pointer-events-none art:absolute art:z-20" initial={{ opacity: 0, left: pct(tip.left), top: pct(tip.top) }} animate={{ opacity: 1, left: pct(tip.left), top: pct(tip.top) }} exit={{ opacity: 0, transition: instant(TIP_EXIT) }} transition={instant(ARTEMIS_SPRING_SWAP)}>
                        <motion.div className="art:w-48 art:rounded-2xl art:border art:border-border art:bg-background art:p-3" style={{ marginLeft: tip.flip ? -14 : 14, originX: tip.flip ? 1 : 0 }} initial={{ scale: 0.96, x: tip.flip ? "-100%" : 0 }} animate={{ scale: 1, x: tip.flip ? "-100%" : 0 }} transition={instant(ARTEMIS_SPRING_SWAP)}>
                          <div className="art:flex art:items-baseline art:justify-between art:gap-2">
                            <p className="art:font-medium art:text-sm">{`Oct ${tip.date}`}</p>
                            <p className="art:font-mono art:text-xs art:tabular-nums">{k(tip.total)}</p>
                          </div>
                          <ul className="art:mt-2 art:space-y-1">
                            {SERIES.map((s, i) => visible[i] ? (<li key={s.key} className="art:flex art:items-center art:justify-between art:gap-2 art:text-xs">
                                  <span className="art:flex art:items-center art:gap-1.5 art:text-muted-foreground">
                                    <span className={`art:size-1.5 art:rounded-full ${s.color}`}/>
                                    {s.label}
                                  </span>
                                  <span className="art:font-mono art:tabular-nums">{k(tip.day[i])}</span>
                                </li>) : null)}
                          </ul>
                        </motion.div>
                      </motion.div>)}
                  </AnimatePresence>
                  <div className="art:flex art:h-full art:items-end art:gap-1" onPointerLeave={() => setActive(null)}>
                    {shown.map((day, i) => {
            const total = totalOf(day);
            const on = active === i;
            const date = first + i + 1;
            return (<button key={`${range}-${date}`} ref={(el) => {
                    bars.current[i] = el;
                }} type="button" className={BAR} tabIndex={roving === i ? 0 : -1} aria-label={`Oct ${date}: ${k(total)}`} aria-pressed={on} onPointerEnter={() => setActive(i)} onFocus={() => setActive(i)} onBlur={() => setActive((a) => (a === i ? null : a))} onKeyDown={(e) => onBarKey(e, i)}>
                          <span aria-hidden="true" className={`art:pointer-events-none art:absolute art:inset-y-0 art:left-1/2 art:w-px art:-translate-x-1/2 art:bg-foreground/15 art:transition-opacity art:duration-150 ${on ? "art:opacity-100" : "art:opacity-0"}`}/>
                          <motion.span aria-hidden="true" className="art:relative art:flex art:h-full art:w-full art:flex-col-reverse art:overflow-hidden art:rounded-md" style={{ originY: 1 }} initial={{ scaleY: 0, opacity: 1 }} animate={{ scaleY: total / DOMAIN, opacity: active !== null && !on ? 0.35 : 1 }} transition={{ scaleY: grow(i), opacity: instant(DIM) }}>
                            {SERIES.map((s, si) => (<motion.span key={s.key} className={`art:block art:w-full ${s.color}`} style={{ flexBasis: 0 }} initial={{ flexGrow: 0, opacity: 1 }} animate={{ flexGrow: visible[si] ? day[si] : 0, opacity: highlight !== null && highlight !== si ? 0.25 : 1 }} transition={{ flexGrow: instant(ARTEMIS_SPRING_LAYOUT), opacity: instant(DIM) }}/>))}
                          </motion.span>
                        </button>);
        })}
                    {Array.from({ length: projectedCount }, (_, j) => {
            const i = shown.length + j;
            const date = first + i + 1;
            return (<button key={`${range}-${date}`} type="button" className={BAR} disabled tabIndex={-1} aria-label={`Oct ${date}, projected ${k(average)}`} aria-pressed="false">
                          <span aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-y-0 art:left-1/2 art:w-px art:-translate-x-1/2 art:bg-foreground/15 art:transition-opacity art:duration-150 art:opacity-0"/>
                          <motion.span aria-hidden="true" className="art:relative art:flex art:h-full art:w-full art:flex-col-reverse art:overflow-hidden art:rounded-md art:border art:border-foreground/25 art:border-dashed" style={{ originY: 1 }} initial={{ scaleY: 0, opacity: 1 }} animate={{ scaleY: average / DOMAIN, opacity: 1 }} transition={{ scaleY: grow(i), opacity: instant(DIM) }}/>
                        </button>);
        })}
                  </div>
                </div>
                <div aria-hidden="true" className="art:relative art:mt-3 art:h-4 art:font-mono art:text-muted-foreground art:text-xs">
                  <span className="art:absolute art:top-0 art:whitespace-nowrap art:left-0">{`Oct ${first + 1}`}</span>
                  {range === "cycle" ? (<span className="art:absolute art:top-0 art:whitespace-nowrap art:-translate-x-1/2 art:text-foreground" style={{ left: `${((TODAY + 0.5) / count) * 100}%` }}>
                      <span className="art:hidden art:@min-[640px]/artemis:inline">
                        {"Today"}
                        {" \u00B7 "}
                      </span>
                      {`Oct ${TODAY + 1}`}
                    </span>) : null}
                  <span className="art:absolute art:top-0 art:whitespace-nowrap art:right-0">{`Oct ${first + count}`}</span>
                </div>
              </figure>
              <div className="art:flex art:flex-wrap art:gap-2 art:mt-5 art:border-border art:border-t art:pt-5">
                {SERIES.map((s) => {
            const off = hidden.has(s.key);
            const lastOn = !off && SERIES.length - hidden.size === 1;
            return (<motion.button key={s.key} type="button" className={`${LEGEND}${off ? " art:opacity-50" : ""} art:rounded-full`} aria-pressed={!off} aria-disabled={lastOn || undefined} tabIndex={0} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => !lastOn && toggle(s.key)}>
                      <span className={`art:size-2 art:rounded-full art:transition-transform art:duration-200 ${s.color}${off ? " art:scale-50" : ""}`}/>
                      {s.label}
                    </motion.button>);
        })}
              </div>
            </motion.div>
            <motion.div className="art:min-w-0 art:rounded-3xl art:border art:border-border art:p-5 art:@min-[640px]/artemis:p-6" initial={REVEAL_HIDDEN} animate={REVEAL_SHOWN} transition={instant(reveal(0.24))}>
              <h3 className="art:font-medium art:text-xl">{"Top workflows"}</h3>
              <p className="art:mt-1 art:text-muted-foreground art:text-sm">{"Change versus the previous cycle"}</p>
              <ul className="art:mt-5 art:space-y-1">
                {WORKFLOWS.map((w, i) => {
            const s = SERIES[w.series];
            const faded = highlight !== null && highlight !== w.series;
            return (<li key={w.name} className={`art:flex art:items-center art:gap-3 art:rounded-2xl art:py-2.5 art:transition-opacity art:duration-200${faded ? " art:opacity-40" : ""}`} onPointerEnter={() => setHighlight(w.series)} onPointerLeave={() => setHighlight((h) => (h === w.series ? null : h))}>
                      <div className="art:min-w-0 art:flex-1">
                        <p className="art:truncate art:font-medium art:text-sm">{w.name}</p>
                        <p className="art:mt-0.5 art:flex art:items-center art:gap-1.5 art:text-muted-foreground art:text-xs">
                          <span className={`art:size-1.5 art:rounded-full ${s.color}`}/>
                          {s.label}
                        </p>
                      </div>
                      <svg viewBox="0 0 64 24" className="art:h-6 art:w-16 art:shrink-0 art:overflow-visible" aria-hidden="true">
                        <motion.polyline points={w.points} pathLength="1" fill="none" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" strokeDasharray="1 1" className={s.stroke} initial={{ strokeDashoffset: 1 }} animate={{ strokeDashoffset: 0 }} transition={instant({ duration: 0.9, ease: ARTEMIS_EASE_OUT, delay: 0.5 + i * 0.08 })}/>
                      </svg>
                      <div className="art:w-16 art:shrink-0 art:text-right">
                        <p className="art:font-mono art:text-sm art:tabular-nums">{w.value}</p>
                        <p className="art:mt-0.5 art:inline-flex art:items-center art:gap-0.5 art:font-mono art:text-muted-foreground art:text-xs art:tabular-nums">
                          {w.up ? (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-3" aria-hidden="true">
                              <path d="M7 7h10v10"/>
                              <path d="M7 17 17 7"/>
                            </svg>) : (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-down-right art:size-3" aria-hidden="true">
                              <path d="m7 7 10 10"/>
                              <path d="M17 7v10H7"/>
                            </svg>)}
                          {w.pct}
                          {"%"}
                          <span className="art:sr-only">{w.up ? "increase" : "decrease"}</span>
                        </p>
                      </div>
                    </li>);
        })}
              </ul>
            </motion.div>
          </div>
        </div>
      </section>
    </>);
}
function Stat({ label, value, badge }: {
    label: string;
    value: string;
    badge?: ReactNode;
}) {
    return (<div className="art:flex art:flex-col-reverse art:gap-1 art:rounded-3xl art:border art:border-border art:p-5">
      <dt className="art:text-muted-foreground art:text-sm">{label}</dt>
      <dd className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-3">
        <span className="art:font-medium art:text-4xl art:tracking-tight">
          <NumberTicker text={value}/>
        </span>
        {badge}
      </dd>
    </div>);
}

"use client";
// @zeus-internal
import { ArtemisRollingNumber } from "../../../../lib/rolling-number";
